mapper.select:
SELECT
    id, process_instance_id, applicant_id, applicant_name,
    dept_id, dept_name, leave_type, start_date, end_date,
    days, reason, status, current_task, create_time, update_time
FROM biz_leave_request
WHERE applicant_id = #{applicantId}

    AND status = #{req.status}


    AND leave_type = #{req.leaveType}

ORDER BY create_time DESC

SELECT r.id, r.process_instance_id, r.applicant_id, r.applicant_name, r.dept_id, r.dept_name, r.leave_type, r.start_date, r.end_date, r.days, r.reason, r.status, r.current_task, r.create_time, r.update_time FROM biz_leave_request r WHERE r.status = 'pending' AND EXISTS ( SELECT 1 FROM sys_user_role_rela ur INNER JOIN sys_role_perm_rela rp ON ur.role_id = rp.role_id INNER JOIN sys_permission p ON rp.ac_id = p.ac_id INNER JOIN sys_user u ON ur.user_id = u.user_id WHERE u.login_name = #{loginName} AND p.ac_url LIKE '%/leave/approval%' )
AND r.leave_type = #{req.leaveType}
ORDER BY r.create_time DESC

SELECT
    id, process_instance_id, applicant_id, applicant_name,
    dept_id, dept_name, leave_type, start_date, end_date,
    days, reason, status, current_task, create_time, update_time
FROM biz_leave_request
WHERE 1=1

    AND status = #{req.status}


    AND leave_type = #{req.leaveType}


    AND applicant_id = #{req.applicantId}


    AND applicant_name LIKE CONCAT('%', #{req.applicantName}, '%')


    AND dept_id = #{req.deptId}


    AND start_date >= #{req.startDateBegin}


    AND start_date <= #{req.startDateEnd}

ORDER BY create_time DESC
